-- ═══════════════════════════════════════════════════════════════
-- ACTIVACIÓN POR DEFECTO: Bolivia (La Paz)
-- Solo la zona horaria de Bolivia se activa por defecto.
-- El resto se activan bajo demanda (cuando hay operaciones en esa zona).
-- ═══════════════════════════════════════════════════════════════
UPDATE bglobal.geo_timezone SET is_active = false;
UPDATE bglobal.geo_timezone SET is_active = true WHERE timezone_id = 'America/La_Paz';

